code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    boxes = []
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        if not pts:
            continue
        r0 = min(r for r, c in pts); r1 = max(r for r, c in pts)
        c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if (all(g[r0][c] == color for c in range(c0, c1+1)) and
            all(g[r1][c] == color for c in range(c0, c1+1)) and
            all(g[r][c0] == color for r in range(r0, r1+1)) and
            all(g[r][c1] == color for r in range(r0, r1+1))):
            boxes.append((color, r0, r1, c0, c1))
    sources = []
    for box in boxes:
        color, r0, r1, c0, c1 = box
        if any(g[r][c] == color for r in range(r0+1, r1) for c in range(c0+1, c1)):
            sources.append(box)
    if not sources:
        return g
    source = max(sources, key=lambda b: sum(g[r][c] == b[0] for r in range(b[1]+1,b[2]) for c in range(b[3]+1,b[4])))
    sc, sr0, sr1, sc0, sc1 = source
    pattern = [[g[r][c] == sc for c in range(sc0+1, sc1)] for r in range(sr0+1, sr1)]
    sh, sw = len(pattern), len(pattern[0])
    for color, r0, r1, c0, c1 in boxes:
        if (color, r0, r1, c0, c1) == source:
            continue
        ih, iw = r1-r0-1, c1-c0-1
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                g[r][c] = 0
        if (ih, iw) == (sh, sw):
            for dr in range(ih):
                for dc in range(iw):
                    if pattern[dr][dc]:
                        g[r0+1+dr][c0+1+dc] = color
            for c in range(c0, c1+1):
                g[r0][c] = g[r1][c] = color
            for r in range(r0, r1+1):
                g[r][c0] = g[r][c1] = color
    return g
